// src/lib/widgets/register.js
//
// Partner-Widgets (Welle 4, Paket WIDGETS; Masterplan B5/B7/B11 „Widgets und White-Label für Stadtwerke“).
//
// Einbettbare Mini-Werkzeuge für Stadtwerke, Gemeindewerke und Verbände: schlanke HTML-Seiten unter
// /widgets/<name>, die ein Partner per <iframe> in die eigene Website einbettet. Grundsätze (DSGVO):
//
//  - KEINE Cookies, KEIN Tracking, KEIN JavaScript im Embed: Die Widgets sind reines HTML + Inline-CSS,
//    der Spar-Kurzrechner rechnet serverseitig über ein GET-Formular. Es entsteht kein Besucherprofil.
//  - Die Partner-Kennung (?partner=…) dient NUR dem Lead-Herkunftsnachweis: Sie wird an die Links aus dem
//    Widget heraus als utm_source/utm_medium angehängt; die Lead-Kette ordnet sie serverseitig über
//    herkunftBereinigen() (src/lib/gruppe/kanal.js) dem Kanal „Partner“ zu – nur WIRKSAME Kennungen aus dem
//    Partner-Register zählen, alles andere fällt auf „Kampagne“ zurück. Keine Provisionslogik.
//  - Einbettung: Die Widget-Routen geben eine EIGENE CSP mit frame-ancestors aus (Standard: * – jede Seite
//    darf einbetten; per Umgebungsvariable WIDGET_FRAME_ANCESTORS auf eine Positivliste einschränkbar,
//    z. B. "https://www.stadtwerk-beispiel.at https://*.verband.at"). Die globalen Kopfzeilen
//    (frame-ancestors 'self', X-Frame-Options) nehmen /widgets/ deshalb aus (next.config.mjs).
//  - Attribution: Jedes Widget trägt sichtbar „bereitgestellt von ÖkoInvest“ mit Link.
//  - noindex: Widgets sind keine eigenständigen Seiten (X-Robots-Tag und <meta name="robots">).
//
// Dieses Modul ist reine Konfiguration + Hilfsfunktionen ohne I/O (testbar mit node --test).

import { kennungFinden, kennungGueltig, mediumFuerArt } from "../gruppe/partner-register.js";

/** Länder, für die Widgets ausgespielt werden (Kleinbuchstaben wie im URL-Parameter ?land=). */
export const WIDGET_LAENDER = Object.freeze(["de", "at", "ch"]);

/** Sprachen der Widget-Texte. */
export const WIDGET_SPRACHEN = Object.freeze(["de", "en"]);

/** Register der Widgets (Stufe 1). Pfad = /widgets/<id>. */
export const WIDGETS = Object.freeze({
  "eg-sparrechner": Object.freeze({
    id: "eg-sparrechner",
    titel: "EG-Spar-Kurzrechner",
    titelEn: "Energy community quick calculator",
    beschreibung: "Grobe Jahres-Näherung der Ersparnis in einer Energiegemeinschaft (Österreich) – vereinfachte Eingaben, gerechnet mit dem Rechenkern des Energiegemeinschafts-Rechners.",
    beschreibungEn: "Rough annual estimate of savings in an energy community (Austria) – simplified inputs, computed with the same engine as the full calculator.",
    laender: Object.freeze(["at"]), // Rechenkern und Regeltabellen gelten für Österreich; DE/CH zeigen einen Hinweis
    hoehe: 560, // empfohlene iframe-Höhe in px (Einbettungs-Snippet)
  }),
  fristen: Object.freeze({
    id: "fristen",
    titel: "Fristen-Ticker",
    titelEn: "Deadline ticker",
    beschreibung: "Die nächsten Förder- und Gebotsfristen des Landes aus dem Faktenregister – mit Quelle und Stand, abgelaufene Einträge verschwinden automatisch.",
    beschreibungEn: "Upcoming funding and bidding deadlines for the selected country from the fact register – with source and date; expired items disappear automatically.",
    laender: WIDGET_LAENDER,
    hoehe: 420,
  }),
});

export const WIDGET_IDS = Object.freeze(Object.keys(WIDGETS));

/**
 * ?land=… bereinigen: Unbekanntes fällt auf das Standard-Land des Widgets zurück. Ein BEKANNTES Land
 * bleibt aber auch dann erhalten, wenn das Widget es (noch) nicht rechnet – das Widget zeigt dann den
 * ehrlichen Länderhinweis statt stillschweigend mit Werten eines anderen Landes zu rechnen.
 */
export function widgetLand(roh, widgetId) {
  const l = typeof roh === "string" ? roh.toLowerCase() : "";
  if (WIDGET_LAENDER.includes(l)) return l;
  return (WIDGETS[widgetId]?.laender || WIDGET_LAENDER)[0];
}

/** ?sprache=… bereinigen (Standard de). */
export const widgetSprache = (roh) => (roh === "en" ? "en" : "de");

/**
 * ?partner=… bereinigen – NUR formale Prüfung (Slug-Muster aus dem Partner-Register), kein Registerzwang:
 * Auch eine formal gültige, noch nicht eingetragene Kennung darf im Link stehen; die Lead-Kette stuft sie
 * dann serverseitig als „Kampagne“ ein (herkunftBereinigen). Ungültige Werte werden verworfen (null).
 */
export const widgetPartner = (roh) => (kennungGueltig(roh) ? roh : null);

/**
 * utm-Parameter für Links aus dem Widget heraus (Lead-Herkunftsnachweis).
 * Mit eingetragener Kennung: utm_medium passend zur Partnerart (gruppe|partner); sonst "partner".
 * Rückgabe: URLSearchParams-tauglicher Eintrag { utm_source, utm_medium, utm_campaign } oder null ohne Kennung.
 */
export function utmFuerPartner(partner, widgetId, optionen = {}) {
  if (!kennungGueltig(partner)) return null;
  const eintrag = kennungFinden(partner, optionen);
  return {
    utm_source: partner,
    utm_medium: eintrag ? mediumFuerArt(eintrag.art) : "partner",
    utm_campaign: `widget-${WIDGETS[widgetId] ? widgetId : "unbekannt"}`,
  };
}

/** Absolute Ziel-URL eines Links aus dem Widget heraus, inkl. utm-Nachweis. */
export function widgetZiel(basis, pfad, { partner = null, widgetId = "" } = {}) {
  const url = new URL(pfad, basis);
  const utm = utmFuerPartner(partner, widgetId);
  if (utm) for (const [k, v] of Object.entries(utm)) url.searchParams.set(k, v);
  return url.toString();
}

const ANCESTOR = /^(\*|'self'|'none'|https?:\/\/[a-z0-9*][a-z0-9.*-]*(:\d{1,5})?)$/i;

/**
 * frame-ancestors aus der Umgebungsvariable WIDGET_FRAME_ANCESTORS (durch Leerzeichen getrennte Quellen).
 * Standard "*": jede Seite darf einbetten (Entscheidung Stufe 1 – die Widgets zeigen nur öffentliche
 * Informationen, keine Personendaten; dokumentiert auf /partner/widgets). TODO-Inhaber: Für den Betrieb
 * entscheiden, ob eine Positivliste der Partner-Domains gesetzt wird. Ungültige Einträge werden verworfen;
 * bleibt nichts übrig, gilt wieder "*".
 */
export function frameAncestors(wert = process.env.WIDGET_FRAME_ANCESTORS) {
  const teile = String(wert || "").trim().split(/\s+/).filter(Boolean).filter((t) => ANCESTOR.test(t));
  if (!teile.length) return "*";
  if (teile.includes("*")) return "*";
  return teile.join(" ");
}

/**
 * Antwort-Kopfzeilen einer Widget-Route: eigene CSP (kein Skript, keine fremden Quellen, Einbettung laut
 * frameAncestors), noindex, keine Cookies nötig → zwischenspeicherbar.
 */
export function widgetKopfzeilen({ ancestors = frameAncestors(), maxAge = 600 } = {}) {
  return {
    "Content-Type": "text/html; charset=utf-8",
    "Content-Security-Policy": [
      "default-src 'none'",
      "style-src 'unsafe-inline'", // nur das eigene Inline-<style>
      "img-src data:",
      "form-action 'self'",
      "base-uri 'none'",
      `frame-ancestors ${ancestors}`,
    ].join("; "),
    "X-Robots-Tag": "noindex, nofollow",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    "X-Content-Type-Options": "nosniff",
    "Cache-Control": `public, max-age=${maxAge}`,
  };
}

/**
 * Einbettungs-Snippet für die Dokumentationsseite /partner/widgets (zum Kopieren).
 * title am iframe = Barrierefreiheit; die Höhe ist eine Empfehlung, das Widget scrollt sonst intern.
 */
export function embedSnippet({ widgetId, land, partner = null, sprache = "de", basis }) {
  const w = WIDGETS[widgetId];
  if (!w) return "";
  const url = new URL(`/widgets/${w.id}`, basis);
  url.searchParams.set("land", widgetLand(land, widgetId));
  if (sprache === "en") url.searchParams.set("sprache", "en");
  if (kennungGueltig(partner)) url.searchParams.set("partner", partner);
  const titel = sprache === "en" ? `${w.titelEn} – ÖkoInvest` : `${w.titel} – ÖkoInvest`;
  return `<iframe src="${url.toString()}" title="${titel}" width="100%" height="${w.hoehe}" style="border:0;border-radius:12px;max-width:640px" loading="lazy"></iframe>`;
}

// src/lib/widgets/egSparKurz.js
//
// EG-Spar-Kurzrechner (Welle 4, Paket WIDGETS): vereinfachte Fassade über den Rechenkern des
// Energiegemeinschafts-Rechners (src/lib/plattform/eg/interesse.js → rechnerOeffentlich).
//
//  - KEINE eigene Rechenlogik: nur drei Eingaben (Jahresverbrauch, Verbrauchsprofil, Modell),
//    alles andere bleibt auf den geprüften Standardannahmen des großen Rechners (AT, Jahr 2026,
//    Rolle „Ich verbrauche“, Deckung „ausgewogen“). Das Ergebnis ist dieselbe Jahres-Näherung,
//    die auch /energiegemeinschaften/rechner zeigt.
//  - Gilt für ÖSTERREICH (Regeltabellen SNE-V/ElWG) – andere Länder bekommen im Widget einen
//    ehrlichen Hinweis statt Zahlen (Vorgabe: keine ungeprüften Werte).
//  - Reine Funktionen ohne I/O; Feinheiten (Hinweise, Annahmen) reicht das Widget sichtbar durch.

import { RECHNER_MODELLE, RECHNER_PROFILE, RECHNER_STANDARD, rechnerOeffentlich } from "../plattform/eg/interesse.js";

/** Auswahl im Kurzrechner (Teilmenge des großen Rechners; GEA weggelassen – zu speziell für ein Embed). */
export const KURZ_PROFILE = Object.freeze(["haushalt", "haushalt_flex", "gewerbe", "landwirtschaft"]);
export const KURZ_MODELLE = Object.freeze(["eeg_lokal", "eeg_regional", "beg"]);

export const KURZ_STANDARD = Object.freeze({
  verbrauchKwh: RECHNER_STANDARD.verbrauchKwh,
  profil: RECHNER_STANDARD.profil,
  modell: RECHNER_STANDARD.modell,
});

const zahl = (v, min, max, std) => {
  const n = typeof v === "string" && v.trim() !== "" ? Number(v.replace(",", ".")) : typeof v === "number" ? v : NaN;
  return Number.isFinite(n) && n >= min && n <= max ? n : std;
};

/** Rohwerte (z. B. aus der Query) → geprüfte Kurzrechner-Eingaben. Unbekanntes fällt auf den Standard. */
export function kurzEingaben(roh = {}) {
  return {
    verbrauchKwh: Math.round(zahl(roh.verbrauchKwh, 100, 1_000_000, KURZ_STANDARD.verbrauchKwh)),
    profil: KURZ_PROFILE.includes(roh.profil) ? roh.profil : KURZ_STANDARD.profil,
    modell: KURZ_MODELLE.includes(roh.modell) ? roh.modell : KURZ_STANDARD.modell,
  };
}

/**
 * Kurzrechnung (Österreich, 2026, Rolle Verbraucher, Deckung ausgewogen) über den gemeinsamen Rechenkern.
 * @returns {{ eingaben, nettoEur, vorteilEur, gebuehrenEur, quotePct, bezugKwh, teile, hinweise, regel, annahmen }}
 */
export function egKurzRechnen(roh = {}) {
  const eingaben = kurzEingaben(roh);
  const r = rechnerOeffentlich({ rolle: "verbraucher", deckung: "ausgewogen", jahr: 2026, ...eingaben });
  return {
    eingaben,
    nettoEur: r.nettoEur,
    vorteilEur: r.vorteilEur,
    gebuehrenEur: r.gebuehrenEur,
    quotePct: r.quotePct,
    bezugKwh: r.bezugKwh,
    teile: r.teile,
    hinweise: r.hinweise,
    regel: r.regel,
    annahmen: r.annahmen,
  };
}

/** Anzeige-Label der Auswahloptionen (de/en) – Texte eigenständig, damit das Widget ohne React-Wörterbuch auskommt. */
export const KURZ_TEXTE = Object.freeze({
  de: Object.freeze({
    profile: Object.freeze(Object.fromEntries(KURZ_PROFILE.map((p) => [p, `${RECHNER_PROFILE[p].label} (${RECHNER_PROFILE[p].sub})`]))),
    modelle: Object.freeze(Object.fromEntries(KURZ_MODELLE.map((m) => [m, `${RECHNER_MODELLE[m].label} – ${RECHNER_MODELLE[m].sub}`]))),
  }),
  en: Object.freeze({
    profile: Object.freeze({
      haushalt: "Household (often away during the day)",
      haushalt_flex: "Flexible household (heat pump, EV, home office)",
      gewerbe: "Business (daytime consumption on weekdays)",
      landwirtschaft: "Farm (milking, cooling, drying)",
    }),
    modelle: Object.freeze({
      eeg_lokal: "REC local – same transformer station",
      eeg_regional: "REC regional – same substation",
      beg: "CEC – Austria-wide",
    }),
  }),
});
// src/lib/widgets/fristenTicker.js
//
// Fristen-Ticker (Welle 4, Paket WIDGETS): die nächsten Fristen eines Landes aus dem Faktenregister,
// aufbereitet für das Embed /widgets/fristen.
//
//  - Auswahl und Datumstexte kommen aus dem bestehenden Baustein src/components/Fakten/FristenListe.js
//    (fristenFuer: keine Entwürfe, keine abgelaufenen Einträge, nach Datum sortiert) – KEINE eigene
//    Auswahl-Logik, damit Website und Widget nie auseinanderlaufen.
//  - Wie dort gilt: keine Countdowns, keine Dringlichkeits-Floskeln – nur Datum, Titel, Quelle, Stand.
//  - Reine Funktionen ohne I/O (testbar mit node --test über das Faktenregister oder eine eigene Liste).

import { fristenFuer, terminText } from "../../components/Fakten/FristenListe.js";
import { anzeigeStatus } from "../fakten/index.js";
import { datumKurzEn, faktEn, quelleTitelEn, terminTextEn } from "../sprache/faktenEn.js";

const datumDe = (iso) => (iso ? `${iso.slice(8, 10)}.${iso.slice(5, 7)}.${iso.slice(0, 4)}` : "");

/**
 * Einträge des Tickers für ein Land ("de" | "at" | "ch"), begrenzt auf `max` (Standard 5).
 * @returns {Array<{ id, titel, terminText, quelleTitel, quelleUrl, stand, geprueft }>}
 */
export function tickerEintraege(landKlein, { heute = new Date(), max = 5, sprache = "de", liste } = {}) {
  const land = String(landKlein || "").toUpperCase();
  if (!["DE", "AT", "CH"].includes(land)) return [];
  const en = sprache === "en";
  return fristenFuer(land, { heute, liste })
    .slice(0, Math.max(1, max))
    .map((f) => {
      const status = anzeigeStatus(f, heute);
      return {
        id: f.id,
        titel: (en && faktEn(f.id, "titel")) || f.wert.titel || "",
        terminText: en ? terminTextEn(f.wert) : terminText(f.wert),
        quelleTitel: en ? quelleTitelEn(f.quelle) : f.quelle?.titel || "",
        quelleUrl: f.quelle?.url || "",
        stand: f.abruf ? (en ? `As at ${datumKurzEn(f.abruf)}` : `Stand ${datumDe(f.abruf)}`) : "",
        geprueft: status === "geprueft",
      };
    });
}
// /widgets/eg-sparrechner – Embed-Route des EG-Spar-Kurzrechners (Welle 4, Paket WIDGETS)
//
//   GET ?land=at&sprache=de|en&partner=<kennung>&verbrauchKwh=&profil=&modell=
//
// Liefert ein in sich geschlossenes HTML-Dokument (kein JavaScript, keine Cookies, kein Tracking),
// das Partner per <iframe> einbetten. Berechnung serverseitig über den Rechenkern des
// Energiegemeinschafts-Rechners (src/lib/widgets/egSparKurz.js). Einbettung erlaubt die eigene CSP
// dieser Route (frame-ancestors, konfigurierbar über WIDGET_FRAME_ANCESTORS); die globalen
// Kopfzeilen nehmen /widgets/ dafür aus (next.config.mjs). Dokumentation: /partner/widgets.

import { widgetDokument } from "@/lib/widgets/html";
import { widgetKopfzeilen, widgetLand, widgetPartner, widgetSprache } from "@/lib/widgets/register";

export const dynamic = "force-dynamic";

export async function GET(request) {
  const url = new URL(request.url);
  const q = url.searchParams;
  const html = widgetDokument({
    widgetId: "eg-sparrechner",
    land: widgetLand(q.get("land"), "eg-sparrechner"),
    sprache: widgetSprache(q.get("sprache")),
    partner: widgetPartner(q.get("partner")),
    basis: url.origin,
    query: { verbrauchKwh: q.get("verbrauchKwh") ?? undefined, profil: q.get("profil") ?? undefined, modell: q.get("modell") ?? undefined },
  });
  return new Response(html, { headers: widgetKopfzeilen() });
}
// /widgets/fristen – Embed-Route des Fristen-Tickers (Welle 4, Paket WIDGETS)
//
//   GET ?land=de|at|ch&sprache=de|en&partner=<kennung>
//
// Liefert ein in sich geschlossenes HTML-Dokument (kein JavaScript, keine Cookies, kein Tracking)
// mit den nächsten Fristen des Landes aus dem Faktenregister (src/lib/widgets/fristenTicker.js –
// dieselbe Auswahl wie /marktdaten/fristen). Einbettung erlaubt die eigene CSP dieser Route
// (frame-ancestors, konfigurierbar über WIDGET_FRAME_ANCESTORS); die globalen Kopfzeilen nehmen
// /widgets/ dafür aus (next.config.mjs). Dokumentation: /partner/widgets.

import { widgetDokument } from "@/lib/widgets/html";
import { widgetKopfzeilen, widgetLand, widgetPartner, widgetSprache } from "@/lib/widgets/register";

export const dynamic = "force-dynamic";

export async function GET(request) {
  const url = new URL(request.url);
  const q = url.searchParams;
  const html = widgetDokument({
    widgetId: "fristen",
    land: widgetLand(q.get("land"), "fristen"),
    sprache: widgetSprache(q.get("sprache")),
    partner: widgetPartner(q.get("partner")),
    basis: url.origin,
  });
  // Fristen ändern sich selten, aber abgelaufene Einträge sollen zügig verschwinden → 10 Minuten
  return new Response(html, { headers: widgetKopfzeilen({ maxAge: 600 }) });
}

// src/lib/widgets/html.js
//
// HTML-Renderer der Partner-Widgets (Welle 4, Paket WIDGETS). Erzeugt vollständige, in sich
// geschlossene HTML-Dokumente für die Embed-Routen /widgets/<name>:
//
//  - reines HTML + Inline-CSS, KEIN JavaScript, keine externen Ressourcen (CSP default-src 'none');
//  - der Kurzrechner arbeitet mit einem GET-Formular auf sich selbst (serverseitige Berechnung);
//  - alle Links hinaus tragen target="_top" (brechen aus dem iframe aus) und den utm-Herkunftsnachweis
//    der Partner-Kennung (src/lib/widgets/register.js → widgetZiel);
//  - Attribution „bereitgestellt von ÖkoInvest“ ist fest eingebaut;
//  - Farben entsprechen den Marken-Tokens aus src/app/globals.css (ov/navy/ink).
//
// Reine Funktionen (String-Bau), testbar mit node --test.

import { KURZ_MODELLE, KURZ_PROFILE, KURZ_TEXTE, egKurzRechnen } from "./egSparKurz.js";
import { tickerEintraege } from "./fristenTicker.js";
import { WIDGETS, widgetZiel } from "./register.js";

/** HTML-Escaping für Textknoten und Attributwerte. */
export const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

const eur = (n, en) => new Intl.NumberFormat(en ? "en-IE" : "de-AT", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(Number(n) || 0);
const zahlFmt = (n, en) => new Intl.NumberFormat(en ? "en-IE" : "de-AT", { maximumFractionDigits: 0 }).format(Number(n) || 0);

const CSS = `
